def safe_line(event, data):
    parts = [event]
    for key, value in data.items():
        parts.append(f"{key}={value}")
    return " ".join(parts)

solution:
SENSITIVE = {"password", "token", "secret", "card"}


def safe_line(event, data):
    parts = [event]
    for key, value in data.items():
        shown = "***" if key.lower() in SENSITIVE else value
        parts.append(f"{key}={shown}")
    return " ".join(parts)

